# Libraries :
from pathlib import Path
import numpy as np
import pandas as pd
from datetime import datetime, timedelta

####################################
### Configuration  ###
####################################

SEED = 42

# Create random generator for reproducibility 
rng = np.random.default_rng(SEED)

# Input Path
SCRIPT_DIR = Path(__file__).resolve().parent

# These scripts uses members_full.csv and member_devices_full.csv exported from PostgreSQL.  
# Inside these csv files are included "member_id" and "device_id" generated by the database.
MEMBERS_PATH = SCRIPT_DIR / "members_full.csv"
MEMBER_DEVICES_PATH = SCRIPT_DIR / "member_devices_full.csv"

# Output Path
REPO_ROOT = Path(__file__).resolve().parents[1]
OUTPUT_PATH = REPO_ROOT / "data" / "raw" / "wearable_readings_raw.csv"

#############################
### Dictionaries of lists ###
#############################

# Use members_full.csv and extract 'member_id' and its corresponding 'date_of_birth' 
members_dict = {
    'member_id': [],
    'date_of_birth': []
}

# Use member_devices_full.csv to extract 'member_id and the 'device_id' that is assigned
member_devices_dict = {
    'member_id': [],
    'device_id': []
}

# Use a dictionary to store simulated wearable readings before converting to DataFrame
# Each key represents a column in the wearable_readings table
# This dictionary accumulates tim-series health readings per member-device pair
readings_dict = {
    'member_id': [],        # Foreign key in the members table
    'device_id': [],        # Foreign key in the devices table
    'recorded_at': [],      # Timestamp of the reading (UTC)
    'heart_rate_bpm': [],   # Heart rate in beats per minute (bpm)
    'systolic_mmHg': [],    # Systolic blook pressure (mmHg)  -> mmHg = unit of pressure for blood pressure
    'diastolic_mmHg': [],   # Diastolic blood pressure (mmHg) 
    'glucose_mg_dl': [],    # Blood glucose pressure ()
    'spo2_pct': []
}

####################################
### Load Functions ###
####################################

# This function loads member data from CSV, parse it with a dataframe and store in a usable python dictionary
def load_members():
    dataframe = pd.read_csv(MEMBERS_PATH)  # Read the members_full.csv file and store in a dataframe
           
    #Conver the whole column "date_of_birth" from list of string to datetime object
    dataframe['date_of_birth'] = pd.to_datetime(dataframe['date_of_birth'])
        
    # Convert "member_id" and "date_of_birth" from pandas.series into a Python standard list and store in members_dict
    members_dict['member_id'] = dataframe['member_id'].tolist()
    members_dict['date_of_birth'] = dataframe['date_of_birth'].tolist()
    
    return

# The main task of his function is to extract and obtain the relationship between members and devices (Which member uses which device)
# It reads the member_devices_full CSV and store in a useful dictionary
def load_member_devices():
    
    dataframe = pd.read_csv(MEMBER_DEVICES_PATH)  # Read the members_devices_full.csv file and store in a dataframe
    
    # Insert "member_id" and "device_id" into member_devices_dict through pandas loop (iterrows) 
    for _, row in dataframe.iterrows():     # Ignore undercore (_), it refers to ignore the index.
        member_devices_dict['member_id'].append(int(row['member_id']))
        member_devices_dict['device_id'].append(int(row['device_id']))

    return


# This function generates a list of timestamps for the simulation period. Example: every 15 minutes for 7 days 
# We have 96 readings per device in 1 day (24h x 4 per hour) 24x4 = 96 
# 100 members x 96 readings per day => 9.600 rows per day
# 9.600 rows x 7 days +> 67.200 readings we are simulating 
def build_timestamps(days=7, freq="15min"):    
        
    start = pd.Timestamp("2026-03-01 00:00:00", tz="UTC")
    end = start + pd.Timedelta(days = days)

    timestamps = pd.date_range(
        start=start,
        end=end,
        freq=freq,          # every 15 minutes according to input parameter
        inclusive="left"    # Include de start but exclude the end to avoid boundary duplication
    )

    return timestamps


# This function caculate the age of a member using the dob (date of birth) and the current date as input
def calculate_age(dob, current_date):
    years = current_date.year - dob.year  # This calculate the current age. It assumes the birthday already happened
    if (current_date.month, current_date.day) < (dob.month, dob.day):   # Check if the person already had their birthday this year 
        years -= 1                                                      # if "NO", then subtract 1 from age
                 
    return years


# This function simulates a biological activity level  (circadian rhythm) using a sine wave model because it matches human rhythms.
# It dependes on the daily hour, lower during late night / early morning, higher during datetime
# Output between -1 and +1
def circadian_wave(hour):
    return np.sin((2 * np.pi / 24) * (hour - 9))  # peak might happen at midnight, with (hours-9), peak (+1) happens around 9 AM


# This function simulates how physically active a person is at a given hour of the day
# It uses rng.uniform for equally values in the range
def activity_level(hour):
    if 0 <= hour < 6:  # Night - sleeping
        level = rng.uniform(0.0, 0.1)  # should be very low movement, low heart rate
    elif 6 <= hour < 9: # Morning - waking up
        level = rng.uniform(0.2, 0.5)  # activity increases, heart rate also increase
    elif 9 <= hour < 18: # Day - working / moving
        level = rng.uniform(0.3, 0.8)  # higher activity, higher heart rate
    elif 18 <= hour < 22: # Evening - relax
        level = rng.uniform(0.2, 0.7)  # Moderate activity, decreate heart rate
    else: # Medium (between 22hs and 23:59hs) 
        level = rng.uniform(0.1, 0.3)  # a random value in a range that represent a medium intensity, very light movement
        
    return level
    
# This function simulates how human heart rate changes over time
# It is based on multiple factors among activity, age, circadian rhythm, emotions. 
def simulate_heart_rate(resting_heart_rate, age, activity, circadian):
    
    hr = resting_heart_rate                 # Start with the base resting heart_rate (55-75 bpm). Calm state
    hr -= age * 0.05                        # Heart rate is also affected by age. Older member tend to have slightly different baselines
    hr += circadian * 5                     # Amplify by 5 the efect of circadian, so it cannot be to small. This value represents how much daily rhythm affect hr.  
    hr += activity * rng.uniform(20, 50)    # Activity effect. Sometimes, activity is light, sometimes more intense
    hr += rng.uniform (-3, 3)               # Add a samll unpredictable variation like breathing, micro-movements
        
    # Add an anomaly event (0.1% to have some very rare anomaly)
    if rng.random() < 0.001:   # rng.random () => can return float number between 0.0 and 1.0
        hr += rng.uniform(40, 100) # if random anomaly, heart rate will increases by 40-100 bpm (stress event) 
        
    # Finally, use clipping function to force heart rate to stay wihthin 20 <= HR <= 250 in case of unrealistic values like negative or extremely high.
    hr = int(np.clip(hr, 20, 250))
    # Lower bound =  20 bpm => extremely low - almost clinical edge case
    # Upper bound = 250 bpm => extremely high - tachycardia
    
    return hr


# This function simulates systolic pressure and diastolic pressure based on age, heart rate and activity
# This is a simulated model, not clinical-grade data
def simulate_blood_pressure(age, heart_rate, activity):
    
    # SYSTOLIC (react to stress, activity)
    base_sys = 105                          # Base systolic pressure
    age_effect = age * 0.4                  # Blood presure tends to increase with age
    hr_effect = (heart_rate - 60) * 0.2     # Heart rate effect.  If heart rate > 60, blood pressure increases, else bood pressure decreases
    activity_effect = activity * 10         # Activity contribution.  Movement increases systolic pressure
   
    # Combine all components to calculate Systolic measure    
    systolic = base_sys + age_effect + hr_effect + activity_effect  # Controlled approximation to simulate realistic data
                
    # DIASTOLIC (more stable, change less)            
    dia_base = 65                               # Base diastolic pressure
    dia_age_effect = age * 0.2                  # Age contribution - smaller effect than systolic
    dia_hr_effect = (heart_rate - 60) * 0.1     # Heart rate contribution (relative to baseline 60 bpm)
    dia_activity_effect = activity * 4          # Activity contribution - moderate impact
        
    # Combine all components
    diastolic = dia_base + dia_age_effect + dia_hr_effect + dia_activity_effect
   
    # Generate rare events (rare anomaly 0.1% chance) due to stress , medical anomaly, exercise, hypertension, etc.
    if rng.random() < 0.001:  
        systolic += rng.uniform(20, 40)   # Add systolic value among +20 to +40 mmHg
        diastolic += rng.uniform(10, 20)  # Add diastolic value among +20 to +40 mmHg

    # Blood pressure is always systolic > diastolic (To ensure blood pressure is physically valid)
    if diastolic >= systolic:
        diastolic = systolic - 10   # Force diastolic slightly lower than systolic. Tunning simulation
   
    # Force systolic, diastolic values to stay within realistic range using clipping functions. Also, convert to int (blood pressure is recorded as integer (120 / 80)
    systolic =  int(np.clip(systolic, 80, 220))  # To make sure systolic is between 80 and 220
    diastolic = int(np.clip(diastolic, 40, 140)) # To make sure diastolic is between 40 and 140
    
    return systolic, diastolic


# This function simulates how blood glucose level changes throughout the day
# It is based on time of day, meals, activity and randomness
def simulate_glucose(age, hour, activity):
    
    # Healthy baseline
    base = rng.uniform(85, 100)         # Starting with baseline glucose 85-100 mg/dL
    
    # Age effect (small effect)
    base += age * rng.uniform(0.05, 0.15) # Age tend to drift upward slightly do to natural changes in metabolism, lower insulin sensitivity, etc.   
         
    
    if 4 <= hour <= 7:                  # Dawn
        base += rng.uniform(5, 15)
    elif 7 < hour <= 9:                 # Breakfast spike
        base += rng.uniform(20, 40)
    elif 9 < hour <= 12:                # Post-breakfast decay
        base += rng.uniform(5, 15)
    elif 12 < hour <= 14:               # Lunch spike
        base += rng.uniform(25, 50)
    elif 14 < hour <= 19:               # Post-lunch decay
        base += rng.uniform(5, 20)
    elif 19 < hour <= 21:               # Dinner spike
        base += rng.uniform(20, 45)
    else:                               # Night (return to baseline)
        base += rng.uniform(-5, 5)     
         

    # Simulate activity effect in glucose
    # Activity like exercise, lowers glucose 
    base -= activity * rng.uniform(3, 10)

    # Simulate anomaly (0.1% chance) - Sugary meal, stress, diabetic
    if rng.random() < 0.001:
        base += rng.uniform(40, 100)

    # Force clipping values between 60 (low glucuse) to 300 (very high glucose). 
    # Clipping function will to avoid negative glucose or extreme unrealistic values. Glucose is measured in whole mg/dL (integer datatype)
    base = int(np.clip(base, 60, 300))
    return base 


# This function simulates blood oxygen saturation (%)
def simulate_spo2(activity):

    # Baseline value.  96% - 99% is considered healthy - normal breathing
    spo2 = rng.uniform(96, 99)

    # Activity effect slighty reduces SpO2
    spo2 -= activity * rng.uniform(0.2, 1.0)  # more activity -> small drop in oxygen

    # Rare anomaly (0.08%) 
    if rng.random() < 0.0008:
        spo2 -= rng.uniform(3, 8)

    # Clipping values to avoid negative or unrealistic values
    # 85% low - 100% maximum
    spo2 = round(np.clip(spo2, 85, 100), 2)  # round with 2 decimal places
    
    return spo2


####################################
### MAIN ###
####################################

load_members()        # Load member_id and date_of_birth from members_full.csv
load_member_devices() # Load member_id and device_id from member_devices_full.csv

# Generates a list of timestamp with 15min frecuency (96 readings) for 7 day
timestamps = build_timestamps(days=7)

# Create readings  (100 member devices x 96 timestamps per day = 9.600 rows per day)

for i in range(len(member_devices_dict['member_id'])):

    member_id = member_devices_dict['member_id'][i]
    device_id = member_devices_dict['device_id'][i]
      
    # Retrieve DOB (Date OF Birth) from members_dict
    index_member = members_dict['member_id'].index(member_id)
    dob = members_dict['date_of_birth'][index_member]
        
    # Base Heart Rate
    resting_heart_rate = rng.integers(55, 75)  # assumes mostly healthy population typical range

    # Create a loop for variables/functions that depends on time (age, circadian, activity, heart_rate, blood_pressure, glucose, spo2)
    for ts in timestamps: # timestamps changes in every iteration
        age = calculate_age(dob, ts)        # Calculate age of a member.  Age can change with some timestamp, so it has to be recalculaed
        hour = ts.hour                      # Extract hour from timestamp to utilize in circadian and activity funtions
        circadian = circadian_wave(hour)    # Circadian depends on time (hour )that changes in every timestamp
        activity = activity_level(hour)
        heart_rate = simulate_heart_rate(resting_heart_rate, age, activity, circadian)
        systolic_bp, diastolic_bp = simulate_blood_pressure(age, heart_rate, activity)
        glucose = simulate_glucose(age, hour, activity)
        spo2 = simulate_spo2(activity)
        
        readings_dict['member_id'].append(member_id)
        readings_dict['device_id'].append(device_id)
        readings_dict['recorded_at'].append(ts.isoformat())
        readings_dict['heart_rate_bpm'].append(heart_rate)
        readings_dict['systolic_mmHg'].append(systolic_bp)
        readings_dict['diastolic_mmHg'].append(diastolic_bp)
        readings_dict['glucose_mg_dl'].append(glucose)
        readings_dict['spo2_pct'].append(spo2)


# Save to CSV
dataframe = pd.DataFrame(readings_dict)
dataframe.to_csv(OUTPUT_PATH, index=False)